<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class TicketDocumentEndpoint {
 public static function register(): void { add_action('init',[self::class,'handle']); }
 public static function handle(): void { if(!isset($_GET['avanik_ticket_download']))return; if(!is_user_logged_in())wp_die('Unauthorized',403); $token=sanitize_text_field(wp_unslash($_GET['avanik_ticket_download'])); $ticket_id=TicketDocumentService::consume_download_token($token,get_current_user_id()); if(!$ticket_id)wp_die('Invalid or expired download token.',403); $ticket=self::find_ticket($ticket_id); if(!$ticket)wp_die('Ticket not found.',404); if(!TicketOperations::can_access($ticket['booking_id']))wp_die('Forbidden',403); $content=TicketPrivateStorage::read($ticket_id); if($content===false){$rendered=TicketPdfRenderer::render($ticket,BookingRepository::find_by_id($ticket['booking_id'])?:[]); if(is_wp_error($rendered))wp_die(esc_html($rendered->get_error_message()),500); $content=$rendered; if(TicketPrivateStorage::save($ticket_id,$content)===false)wp_die('Unable to store ticket document.',500); } nocache_headers(); header('Content-Type: text/html; charset=utf-8'); header('Content-Disposition: inline; filename="'.esc_attr(TicketDocumentService::build_filename($ticket)).'"'); echo $content; exit; }
 private static function find_ticket(string $ticket_id): array|false { global $wpdb; $row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.TicketRepository::table_name().' WHERE ticket_id=%s LIMIT 1',$ticket_id),ARRAY_A); return $row?:false; }
}